import manifest from './manifest.json';
import { ART_FILES } from './art.gen';

/**
 * Pixel icons (docs/plans/pixel-icons.md). A def names its art with `art`, a
 * name from manifest.json; the manifest maps the name to a file under
 * src/assets/, and art.gen.ts (generated by `npm run icons`) holds the URL of
 * every listed file that is on disk. The packs are gitignored, so a checkout
 * without them finds no URL and the icon falls back to the def's emoji —
 * the same arrangement enemy portraits use (enemyArt.ts).
 *
 * Core stays browser-free: art never leaves the UI layer.
 */

/** Icon name → file under src/assets/. The only part of the art in git. */
export const ICON_MANIFEST: Record<string, string> = manifest;

const FROM_HERE = '../../../assets/';

/** URL of a manifest icon, or null when the name is unknown or its file is not on disk. */
export function artUrl(name: string | undefined): string | null {
  if (!name) return null;
  const file = ICON_MANIFEST[name];
  return file ? (ART_FILES[FROM_HERE + file] ?? null) : null;
}

/**
 * The art for a def: its own `art`. (The emoji-keyed glyph table, the second
 * layer of the plan's resolution order, arrives with the log in story 2.)
 */
export function iconUrl(def: { art?: string }): string | null {
  return artUrl(def.art);
}
